var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

var state = {
  temperature: 0.35,
  selection: 'All combinations',
  step: 0
};

var lineDefs = [
  {
    key: 'hp_sn',
    label: 'ΔH > 0, ΔS < 0',
    h: 0.48,
    m: 0.62,
    color: '#c24732',
    lines: ['ΔH > 0', 'ΔS < 0'],
    labelX: 0.34,
    labelOffset: -18,
    popup: 'Positive ΔH puts the line above zero at low temperature. Negative ΔS makes −TΔS positive, so increasing temperature raises ΔG even more.'
  },
  {
    key: 'hp_sp',
    label: 'ΔH > 0, ΔS > 0',
    h: 0.48,
    m: -0.65,
    color: '#ddb313',
    lines: ['ΔH > 0', 'ΔS > 0'],
    labelX: 0.36,
    labelOffset: -18,
    popup: 'Positive ΔH starts nonspontaneous, but positive ΔS gives a negative slope. At high enough temperature this line crosses ΔG = 0.'
  },
  {
    key: 'hn_sn',
    label: 'ΔH < 0, ΔS < 0',
    h: -0.49,
    m: 0.75,
    color: '#ddb313',
    lines: ['ΔH < 0', 'ΔS < 0'],
    labelX: 0.34,
    labelOffset: -20,
    popup: 'Negative ΔH starts spontaneous, but negative ΔS gives a positive slope. At high enough temperature this line crosses into ΔG > 0.'
  },
  {
    key: 'hn_sp',
    label: 'ΔH < 0, ΔS > 0',
    h: -0.49,
    m: -0.55,
    color: '#87ad3a',
    lines: ['ΔH < 0', 'ΔS > 0'],
    labelX: 0.40,
    labelOffset: -18,
    popup: 'Negative ΔH starts below zero. Positive ΔS makes the slope negative, so increasing temperature makes the process even more spontaneous.'
  }
];

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function hexToRgba(hex, a) {
  var h = hex.replace('#', '');
  var r = parseInt(h.substring(0, 2), 16);
  var g = parseInt(h.substring(2, 4), 16);
  var b = parseInt(h.substring(4, 6), 16);
  return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
}

function yOf(def, x) {
  return def.h + def.m * x;
}

function visibleAlpha(def) {
  if (state.selection === 'All combinations') return 1;
  return state.selection === def.label ? 1 : 0.14;
}

function fontSize(chart, factor, lo, hi) {
  var m = Math.min(chart.width || 700, chart.height || 520);
  return clamp(Math.round(m * factor), lo, hi);
}

function makeLineData(def) {
  var pts = [];
  for (var i = 0; i <= 40; i++) {
    var x = i / 40;
    pts.push({ x: x, y: yOf(def, x) });
  }
  return pts;
}

function addHit(chart, item) {
  if (!chart.$hitItems) chart.$hitItems = [];
  chart.$hitItems.push(item);
}

function hitBoxContains(item, x, y) {
  return x >= item.x - item.w / 2 && x <= item.x + item.w / 2 &&
         y >= item.y - item.h / 2 && y <= item.y + item.h / 2;
}

function drawArrow(ctx, x1, y1, x2, y2, color, width, head) {
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.save();
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - head * Math.cos(ang - Math.PI / 6), y2 - head * Math.sin(ang - Math.PI / 6));
  ctx.lineTo(x2 - head * Math.cos(ang + Math.PI / 6), y2 - head * Math.sin(ang + Math.PI / 6));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawRotatedLabel(ctx, chart, def, alpha) {
  var xScale = chart.scales.x;
  var yScale = chart.scales.y;
  var fs = fontSize(chart, 0.034, 10, 22);
  var lineH = fs * 1.25;
  var x = def.labelX;
  var y = yOf(def, x);
  var p1x = xScale.getPixelForValue(0.18);
  var p1y = yScale.getPixelForValue(yOf(def, 0.18));
  var p2x = xScale.getPixelForValue(0.72);
  var p2y = yScale.getPixelForValue(yOf(def, 0.72));
  var ang = Math.atan2(p2y - p1y, p2x - p1x);
  var px = xScale.getPixelForValue(x);
  var py = yScale.getPixelForValue(y);
  var off = def.labelOffset * clamp(Math.min(chart.chartArea.width, chart.chartArea.height) / 430, 0.75, 1.25);
  px += -Math.sin(ang) * off;
  py += Math.cos(ang) * off;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(px, py);
  ctx.rotate(ang);
  ctx.font = 'italic ' + fs + 'px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.lineWidth = Math.max(3, fs * 0.18);
  ctx.fillStyle = '#000';
  for (var i = 0; i < def.lines.length; i++) {
    var ty = (i - 0.5) * lineH;
    ctx.strokeText(def.lines[i], 0, ty);
    ctx.fillText(def.lines[i], 0, ty);
  }
  var w = Math.max(ctx.measureText(def.lines[0]).width, ctx.measureText(def.lines[1]).width) + fs * 1.4;
  ctx.restore();

  addHit(chart, {
    x: px,
    y: py,
    w: w + 12,
    h: lineH * 2.2,
    tooltip: def.label + ': ΔH sets the intercept; −ΔS sets the slope.',
    title: def.label,
    body: def.popup
  });
}

var thermoPlugin = {
  id: 'thermoPlugin',
  beforeDraw: function(chart) {
    var ctx = chart.ctx;
    var ca = chart.chartArea;
    if (!ca) return;
    var y0 = chart.scales.y.getPixelForValue(0);

    ctx.save();
    ctx.fillStyle = '#efd1c8';
    ctx.fillRect(ca.left, ca.top, ca.right - ca.left, y0 - ca.top);
    ctx.fillStyle = '#e5efd5';
    ctx.fillRect(ca.left, y0, ca.right - ca.left, ca.bottom - y0);

    ctx.setLineDash([12, 12]);
    ctx.strokeStyle = '#858585';
    ctx.lineWidth = clamp(Math.min(ca.width, ca.height) * 0.004, 1, 2.2);
    ctx.beginPath();
    ctx.moveTo(ca.left, y0);
    ctx.lineTo(ca.right, y0);
    ctx.stroke();
    ctx.restore();
  },
  afterDatasetsDraw: function(chart) {
    var ctx = chart.ctx;
    var ca = chart.chartArea;
    var xScale = chart.scales.x;
    var yScale = chart.scales.y;
    if (!ca) return;
    chart.$hitItems = [];

    var minDim = Math.min(ca.width, ca.height);
    var regionFont = fontSize(chart, 0.042, 13, 28);
    var sideFont = fontSize(chart, 0.036, 11, 22);
    var y0 = yScale.getPixelForValue(0);

    ctx.save();
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.font = regionFont + 'px Arial, sans-serif';
    ctx.fillStyle = '#000';
    var nx = ca.left + ca.width * 0.62;
    var ny = ca.top + (y0 - ca.top) * 0.55;
    var sx = ca.left + ca.width * 0.62;
    var sy = y0 + (ca.bottom - y0) * 0.52;
    ctx.fillText('Nonspontaneous', nx, ny);
    ctx.fillText('Spontaneous', sx, sy);
    addHit(chart, {
      x: nx + ctx.measureText('Nonspontaneous').width / 2,
      y: ny,
      w: ctx.measureText('Nonspontaneous').width + 12,
      h: regionFont * 1.4,
      tooltip: 'ΔG > 0: nonspontaneous under these conditions.',
      title: 'Nonspontaneous region',
      body: 'Above the dashed boundary, ΔG is positive. A process in this region is not spontaneous at that temperature.'
    });
    addHit(chart, {
      x: sx + ctx.measureText('Spontaneous').width / 2,
      y: sy,
      w: ctx.measureText('Spontaneous').width + 12,
      h: regionFont * 1.4,
      tooltip: 'ΔG < 0: spontaneous under these conditions.',
      title: 'Spontaneous region',
      body: 'Below the dashed boundary, ΔG is negative. A process in this region is thermodynamically spontaneous at that temperature.'
    });
    ctx.restore();

    ctx.save();
    ctx.font = sideFont + 'px Arial, sans-serif';
    ctx.fillStyle = '#000';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.translate(ca.left - sideFont * 1.35, ca.top + (y0 - ca.top) * 0.52);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('ΔG > 0', 0, 0);
    ctx.restore();

    ctx.save();
    ctx.font = sideFont + 'px Arial, sans-serif';
    ctx.fillStyle = '#000';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.translate(ca.left - sideFont * 1.35, y0 + (ca.bottom - y0) * 0.50);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('ΔG < 0', 0, 0);
    ctx.restore();

    for (var i = 0; i < lineDefs.length; i++) {
      drawRotatedLabel(ctx, chart, lineDefs[i], visibleAlpha(lineDefs[i]));
    }

    var t = state.temperature;
    var cursorX = xScale.getPixelForValue(t);
    ctx.save();
    ctx.strokeStyle = 'rgba(35,35,35,0.48)';
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = clamp(minDim * 0.004, 1, 2);
    ctx.beginPath();
    ctx.moveTo(cursorX, ca.top);
    ctx.lineTo(cursorX, ca.bottom);
    ctx.stroke();
    ctx.restore();

    addHit(chart, {
      x: cursorX,
      y: ca.top + ca.height / 2,
      w: 14,
      h: ca.height,
      tooltip: 'Temperature cursor: move the slider to follow ΔG at this temperature.',
      title: 'Temperature cursor',
      body: 'The vertical cursor samples each line at the same temperature. A highlighted point changes spontaneity when it crosses the dashed ΔG = 0 boundary.'
    });

    for (var j = 0; j < lineDefs.length; j++) {
      var def = lineDefs[j];
      var a = visibleAlpha(def);
      if (a < 0.5) continue;
      var yy = yOf(def, t);
      if (yy < -1.04 || yy > 1.08) continue;
      var px = xScale.getPixelForValue(t);
      var py = yScale.getPixelForValue(yy);
      var r = clamp(minDim * 0.017, 4, 8);
      ctx.save();
      ctx.globalAlpha = 0.96;
      ctx.fillStyle = def.color;
      ctx.strokeStyle = yy >= 0 ? '#9b3527' : '#5b8e28';
      ctx.lineWidth = clamp(minDim * 0.006, 1.4, 3);
      ctx.beginPath();
      ctx.arc(px, py, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.restore();

      addHit(chart, {
        x: px,
        y: py,
        w: r * 4,
        h: r * 4,
        tooltip: def.label + ' at this temperature: ΔG ' + (yy >= 0 ? '> 0, nonspontaneous' : '< 0, spontaneous') + '.',
        title: 'ΔG at the cursor',
        body: 'This point is the value of ΔG = ΔH − TΔS for the selected temperature. Its position above or below the dashed line tells whether the process is spontaneous.'
      });
    }

    var selected = null;
    for (var k = 0; k < lineDefs.length; k++) {
      if (lineDefs[k].label === state.selection) selected = lineDefs[k];
    }

    if (selected) {
      var selColor = selected.color;
      var r2 = clamp(minDim * 0.018, 4, 8);
      var yIntY = yScale.getPixelForValue(selected.h);
      var yIntX = xScale.getPixelForValue(0);

      ctx.save();
      ctx.fillStyle = '#fff';
      ctx.strokeStyle = selColor;
      ctx.lineWidth = clamp(minDim * 0.008, 2, 4);
      ctx.beginPath();
      ctx.arc(yIntX, yIntY, r2, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
      addHit(chart, {
        x: yIntX,
        y: yIntY,
        w: r2 * 4,
        h: r2 * 4,
        tooltip: 'Y-intercept: the ΔH starting value.',
        title: 'ΔH as the intercept',
        body: 'At the left edge, the temperature term is smallest in this conceptual plot, so the line begins on the side set by ΔH. Positive ΔH starts above zero; negative ΔH starts below zero.'
      });

      var xa = 0.18, xb = 0.34;
      var ya = yOf(selected, xa), yb = yOf(selected, xb);
      drawArrow(
        ctx,
        xScale.getPixelForValue(xa),
        yScale.getPixelForValue(ya),
        xScale.getPixelForValue(xb),
        yScale.getPixelForValue(yb),
        selColor,
        clamp(minDim * 0.008, 2, 4),
        clamp(minDim * 0.028, 7, 13)
      );
      addHit(chart, {
        x: (xScale.getPixelForValue(xa) + xScale.getPixelForValue(xb)) / 2,
        y: (yScale.getPixelForValue(ya) + yScale.getPixelForValue(yb)) / 2,
        w: 50,
        h: 30,
        tooltip: 'Slope direction comes from −TΔS.',
        title: 'Slope from entropy',
        body: 'Because ΔG = ΔH − TΔS, positive ΔS gives a downward slope as temperature increases, while negative ΔS gives an upward slope.'
      });

      var xi = -selected.h / selected.m;
      if (xi >= 0 && xi <= 1) {
        var ix = xScale.getPixelForValue(xi);
        var iy = yScale.getPixelForValue(0);
        ctx.save();
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = '#111';
        ctx.lineWidth = clamp(minDim * 0.007, 1.8, 3);
        ctx.beginPath();
        ctx.arc(ix, iy, r2 * 1.05, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        ctx.restore();
        addHit(chart, {
          x: ix,
          y: iy,
          w: r2 * 5,
          h: r2 * 5,
          tooltip: 'ΔG = 0 crossing: spontaneity reverses here.',
          title: 'Zero crossing',
          body: 'This intercept is the temperature where ΔG changes sign. Only the same-sign cases, ΔH > 0 with ΔS > 0 or ΔH < 0 with ΔS < 0, can cross zero.'
        });
      }
    }
  }
};

var datasets = lineDefs.map(function(def) {
  return {
    label: def.label,
    data: makeLineData(def),
    parsing: false,
    borderColor: def.color,
    backgroundColor: def.color,
    borderWidth: 5,
    pointRadius: 0,
    pointHoverRadius: 0,
    tension: 0,
    clip: true
  };
});

var chart = new Chart(canvas, {
  type: 'line',
  data: { datasets: datasets },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    normalized: true,
    layout: {
      padding: { top: 2, right: 0, bottom: 0, left: 0 }
    },
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false }
    },
    elements: {
      line: { capBezierPoints: false }
    },
    scales: {
      x: {
        type: 'linear',
        min: 0,
        max: 1,
        grid: { display: false },
        ticks: { display: false },
        border: { display: true, color: '#000', width: 2 },
        title: {
          display: true,
          text: 'Increasing temperature (K)',
          color: '#000',
          padding: { top: 10 },
          font: function(ctx) {
            return { size: fontSize(ctx.chart, 0.041, 12, 26), weight: 'bold', family: 'Arial, sans-serif' };
          }
        }
      },
      y: {
        type: 'linear',
        min: -1,
        max: 1,
        afterBuildTicks: function(axis) {
          axis.ticks = [{ value: 0 }];
        },
        grid: { display: false },
        border: { display: true, color: '#000', width: 2 },
        ticks: {
          color: '#000',
          padding: 8,
          callback: function(value) { return value === 0 ? '0' : ''; },
          font: function(ctx) {
            return { size: fontSize(ctx.chart, 0.036, 10, 21), family: 'Arial, sans-serif' };
          }
        },
        title: {
          display: true,
          text: 'Free energy',
          color: '#000',
          padding: { bottom: 8 },
          font: function(ctx) {
            return { size: fontSize(ctx.chart, 0.042, 12, 26), weight: 'bold', family: 'Arial, sans-serif' };
          }
        }
      }
    }
  },
  plugins: [thermoPlugin]
});
window.__markRendered();

function restyleDatasets() {
  for (var i = 0; i < lineDefs.length; i++) {
    var def = lineDefs[i];
    var a = visibleAlpha(def);
    chart.data.datasets[i].borderColor = hexToRgba(def.color, a);
    chart.data.datasets[i].backgroundColor = hexToRgba(def.color, a);
    chart.data.datasets[i].borderWidth = (state.selection === def.label) ? 7 : 5;
  }
}

function update_temperatureCursor(v) {
  state.temperature = +v;
  chart.update('none');
}

function update_signCombination(v) {
  state.selection = v;
  restyleDatasets();
  chart.update('none');
}

function toggle_signCombination(on) {
  update_signCombination(on ? 'ΔH > 0, ΔS > 0' : 'All combinations');
}

var demoSteps = [
  {
    title: 'Read the zero boundary',
    narration: 'The dashed horizontal line is ΔG = 0. Points above it are nonspontaneous, while points below it are spontaneous.',
    state: { temperatureCursor: 0.25, signCombination: 'All combinations' }
  },
  {
    title: 'Temperature always matters through the slope',
    narration: 'Drag the temperature cursor: each highlighted point moves along its line according to ΔG = ΔH − TΔS. Lines that never cross zero remain always spontaneous or always nonspontaneous.',
    state: { temperatureCursor: 0.65, signCombination: 'All combinations' }
  },
  {
    title: 'Opposite signs: always nonspontaneous',
    narration: 'For ΔH > 0 and ΔS < 0, the process starts above zero and the slope is upward, so increasing temperature only makes ΔG more positive.',
    state: { temperatureCursor: 0.45, signCombination: 'ΔH > 0, ΔS < 0' }
  },
  {
    title: 'Opposite signs: always spontaneous',
    narration: 'For ΔH < 0 and ΔS > 0, the process starts below zero and the slope is downward, so increasing temperature only makes ΔG more negative.',
    state: { temperatureCursor: 0.45, signCombination: 'ΔH < 0, ΔS > 0' }
  },
  {
    title: 'Same positive signs: spontaneous only at high temperature',
    narration: 'For ΔH > 0 and ΔS > 0, the line starts nonspontaneous but slopes downward. Once the temperature cursor passes the ΔG = 0 intercept, the process becomes spontaneous.',
    state: { temperatureCursor: 0.8, signCombination: 'ΔH > 0, ΔS > 0' }
  },
  {
    title: 'Same negative signs: spontaneous only at low temperature',
    narration: 'For ΔH < 0 and ΔS < 0, the line starts spontaneous but slopes upward. At sufficiently high temperature it crosses into the nonspontaneous region.',
    state: { temperatureCursor: 0.8, signCombination: 'ΔH < 0, ΔS < 0' }
  }
];

function applyStep(i) {
  state.step = clamp(i, 0, demoSteps.length - 1);
  var step = demoSteps[state.step];
  var t = step.state.temperatureCursor;
  var s = step.state.signCombination;

  var tInput = document.getElementById('temperatureCursorInput');
  var tVal = document.getElementById('temperatureCursorVal');
  var sInput = document.getElementById('signCombinationInput');
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');

  tInput.value = t;
  tVal.value = t;
  sInput.value = s;
  narr.textContent = step.narration;
  label.textContent = (state.step + 1) + '/' + demoSteps.length;

  state.temperature = t;
  state.selection = s;
  restyleDatasets();
  chart.update('none');
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

canvas.addEventListener('mousemove', function(e) {
  var rect = canvas.getBoundingClientRect();
  var x = e.clientX - rect.left;
  var y = e.clientY - rect.top;
  var items = chart.$hitItems || [];
  var found = null;
  for (var i = items.length - 1; i >= 0; i--) {
    if (hitBoxContains(items[i], x, y)) {
      found = items[i];
      break;
    }
  }
  if (found) {
    canvas.style.cursor = 'pointer';
    showTooltip(found.tooltip, e);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
  }
});

canvas.addEventListener('mouseleave', function() {
  canvas.style.cursor = 'default';
  hideTooltip();
});

canvas.addEventListener('click', function(e) {
  var rect = canvas.getBoundingClientRect();
  var x = e.clientX - rect.left;
  var y = e.clientY - rect.top;
  var items = chart.$hitItems || [];
  for (var i = items.length - 1; i >= 0; i--) {
    if (hitBoxContains(items[i], x, y)) {
      showPopup(items[i].title, items[i].body);
      return;
    }
  }
});

document.addEventListener('fig-resize', function() {
  chart.resize();
});

restyleDatasets();
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: The sign of ΔG = ΔH − TΔS determines spontaneity, so ΔH sets the starting side of the plot while ΔS controls whether increasing temperature raises or lowers ΔG.
KEY INSIGHT (what students should walk away understanding): Only when ΔH and ΔS have the same sign can temperature reverse spontaneity, because only then does the ΔG line cross zero.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The sign of ΔG = ΔH − TΔS determines spontaneity, so ΔH sets the starting side of the plot while ΔS controls whether increasing temperature raises or lowers ΔG.",
  "figureType": "line_plot",
  "elements": [
    "horizontal temperature axis labeled 'Increasing temperature (K)' with no numeric tick labels",
    "vertical free energy axis labeled 'Free energy'",
    "single vertical-axis tick labeled '0'",
    "gray dashed horizontal zero line at ΔG = 0",
    "upper pink background region labeled 'Nonspontaneous'",
    "lower pale green background region labeled 'Spontaneous'",
    "left-side annotation 'ΔG > 0' beside the upper region",
    "left-side annotation 'ΔG < 0' beside the lower region",
    "red line for ΔH > 0, ΔS < 0 beginning above zero and increasing with temperature",
    "red line label 'ΔH > 0, ΔS < 0'",
    "yellow downward-sloping line for ΔH > 0, ΔS > 0 beginning above zero and crossing ΔG = 0 as temperature increases",
    "yellow downward-sloping line label 'ΔH > 0, ΔS > 0'",
    "yellow upward-sloping line for ΔH < 0, ΔS < 0 beginning below zero and crossing ΔG = 0 as temperature increases",
    "yellow upward-sloping line label 'ΔH < 0, ΔS < 0'",
    "green line for ΔH < 0, ΔS > 0 beginning below zero and decreasing with temperature",
    "green line label 'ΔH < 0, ΔS > 0'",
    "vertical temperature cursor controlled by the slider",
    "highlight point where the temperature cursor intersects each visible ΔG line",
    "x-intercept marker where a selected line crosses ΔG = 0",
    "slope arrow or small slope annotation on the selected line",
    "y-intercept marker on the selected line showing the ΔH starting value"
  ],
  "interactions": [
    {
      "id": "temperatureCursor",
      "type": "slider",
      "label": "Temperature",
      "range": [
        0,
        1,
        0.01
      ],
      "default": 0.35,
      "teaches": "As temperature increases, each process moves along its ΔG line; crossing the ΔG = 0 boundary is the moment its spontaneity changes"
    },
    {
      "id": "signCombination",
      "type": "toggle",
      "label": "Sign combination",
      "options": [
        "All combinations",
        "ΔH > 0, ΔS < 0",
        "ΔH > 0, ΔS > 0",
        "ΔH < 0, ΔS < 0",
        "ΔH < 0, ΔS > 0"
      ],
