      line: { capBezierPoints: false }
    },
    scales: {
      x: {
        type: 'linear',
        min: 0,
        max: 1,
        grid: { display: false },
        ticks: { display: false },
        border: { display: true, color: '#000', width: 2 },
        title: {
          display: true,
          text: 'Increasing temperature (K)',
          color: '#000',
          padding: { top: 10 },
          font: function(ctx) {
            return { size: fontSize(ctx.chart, 0.047, 14, 28), weight: 'bold', family: 'Arial, sans-serif' };
          }
        }
      },
      y: {
        type: 'linear',
        min: -1.08,
        max: 1.08,
        afterBuildTicks: function(axis) {
          axis.ticks = [{ value: 0 }];
        },
        grid: { display: false },
        border: { display: true, color: '#000', width: 2 },
        ticks: {
          color: '#000',
          padding: 8,
          callback: function(value) { return value === 0 ? '0' : ''; },
          font: function(ctx) {
            return { size: fontSize(ctx.chart, 0.041, 11, 23), family: 'Arial, sans-serif' };
          }
        },
        title: {
          display: true,
          text: 'Free energy',
          color: '#000',
          padding: { bottom: 8 },
          font: function(ctx) {
            return { size: fontSize(ctx.chart, 0.049, 14, 28), weight: 'bold', family: 'Arial, sans-serif' };
          }
        }
      }
    }
  },
  plugins: [thermoPlugin]
});
window.__markRendered();

function restyleDatasets() {
  for (var i = 0; i < lineDefs.length; i++) {
    var def = lineDefs[i];
    var a = visibleAlpha(def);
    chart.data.datasets[i].borderColor = hexToRgba(def.color, a);
    chart.data.datasets[i].backgroundColor = hexToRgba(def.color, a);
    chart.data.datasets[i].borderWidth = (state.selection === def.label) ? 7 : 5;
  }
}

function update_temperatureCursor(v) {
  state.temperature = +v;
  state.cursorVisible = true;
  chart.update('none');
}

function update_signCombination(v) {
  state.selection = v;
  restyleDatasets();
  chart.update('none');
}

function toggle_signCombination(on) {
  update_signCombination(on ? 'ΔH > 0, ΔS > 0' : 'All combinations');
}

